const ai = $('AI: Классификация письма').item.json.output || {};
const originalEmail = $('Новое письмо').item.json;
const staffItem = $input.item.json;

// Template
let tplText = '';
try {
  const tplRows = $('Sheets: получить шаблон').all();
  if (tplRows.length > 0) tplText = tplRows[0].json.template_text || '';
} catch(e) {}

// Resources list
let resourcesList = '';
try {
  const resRows = $('Sheets: получить ресурсы').all();
  if (resRows.length > 0) {
    resourcesList = '\n\nПолезные ресурсы:\n' + resRows
      .filter(r => !ai.subcategory || r.json.subcategory === ai.subcategory || !r.json.subcategory)
      .map(r => {
        let line = `• ${r.json.name || '—'}`;
        if (r.json.phone) line += `, тел.: ${r.json.phone}`;
        if (r.json.address) line += `, адрес: ${r.json.address}`;
        return line;
      }).join('\n');
  }
} catch(e) {}

// Client history
let clientHistory = 'Новый клиент — записей не найдено';
try {
  const clientRows = $('Sheets: история клиента').all();
  if (clientRows.length > 0) {
    const c = clientRows[0].json;
    clientHistory = `Последний контакт: ${c.last_contact || 'нет данных'}, категория: ${c.last_category || '-'}`;
  }
} catch(e) {}

// Manager contact (housing/problem only)
let managerInfo = '';
try {
  const mgrRows = $('Sheets: найти управдома').all();
  if (mgrRows.length > 0) {
    const m = mgrRows[0].json;
    managerInfo = `\n\n📞 Контакт управдома:\n${m.manager_name || '—'}\nТел.: ${m.manager_phone || '—'}\nЧасы работы: ${m.manager_hours || '—'}`;
  }
} catch(e) {}

const priorityMap = { urgent: '🔴 СРОЧНО', normal: '🟡 ОБЫЧНЫЙ', low: '🟢 НИЗКИЙ' };
const priorityLabel = priorityMap[ai.priority] || ai.priority;

const responseText = tplText || `Уважаемый(ая) клиент,\n\nБлагодарим Вас за обращение в нашу социальную службу.\nВаш запрос принят и будет рассмотрен в ближайшее время.\nЕсли у Вас возникнут дополнительные вопросы, пожалуйста, свяжитесь с нами.\n\nС уважением,\nСоциальная служба`;

const draftBody = `--- РЕЗЮМЕ ДЛЯ СОЦ.РАБОТНИКА (удалить перед отправкой) ---\nКатегория: ${ai.category || '—'} / ${ai.subcategory || '—'}\nПриоритет: ${priorityLabel}\nОт: ${ai.client_data?.name || originalEmail.from}\nУверенность AI: ${Math.round((ai.confidence || 0) * 100)}%\nСуть: ${ai.summary || '—'}\nИстория клиента: ${clientHistory}\nНазначен: ${staffItem.name || staffItem.email || '—'}\n----------------------------------------------------------\n\n${responseText}${resourcesList}${managerInfo}`;

return [{
  json: {
    ...ai,
    draft_body: draftBody,
    staff_email: staffItem.email || '',
    staff_name: staffItem.name || '',
    original_subject: originalEmail.subject || '',
    original_from: originalEmail.from || '',
    client_name: ai.client_data?.name || originalEmail.from
  }
}];

const events = $input.all().map(e => e.json);
const staffData = $('Sheets: выбрать соц.работника B').item.json;

const WORK_START = 9;
const WORK_END = 17;
const SLOT_MIN = 30;

const busyTimes = events
  .filter(e => e.start)
  .map(e => ({
    start: new Date(e.start.dateTime || e.start.date),
    end: new Date(e.end.dateTime || e.end.date)
  }));

const freeSlots = [];
const now = new Date();
const endRange = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

const cursor = new Date(now);
cursor.setSeconds(0, 0);
const mins = cursor.getMinutes();
cursor.setMinutes(mins <= 30 ? 30 : 60, 0, 0);
if (cursor.getHours() < WORK_START) cursor.setHours(WORK_START, 0, 0, 0);

while (freeSlots.length < 3 && cursor < endRange) {
  const day = cursor.getDay();
  if (day === 0 || day === 6) {
    cursor.setDate(cursor.getDate() + (day === 6 ? 2 : 1));
    cursor.setHours(WORK_START, 0, 0, 0);
    continue;
  }
  if (cursor.getHours() >= WORK_END) {
    cursor.setDate(cursor.getDate() + 1);
    cursor.setHours(WORK_START, 0, 0, 0);
    continue;
  }
  const slotEnd = new Date(cursor.getTime() + SLOT_MIN * 60 * 1000);
  if (slotEnd.getHours() > WORK_END || (slotEnd.getHours() === WORK_END && slotEnd.getMinutes() > 0)) {
    cursor.setDate(cursor.getDate() + 1);
    cursor.setHours(WORK_START, 0, 0, 0);
    continue;
  }
  const isBusy = busyTimes.some(b => cursor < b.end && slotEnd > b.start);
  if (!isBusy) {
    freeSlots.push({
      start: cursor.toISOString(),
      end: slotEnd.toISOString(),
      display: cursor.toLocaleString('ru-RU', {
        weekday: 'short', day: 'numeric', month: 'long',
        hour: '2-digit', minute: '2-digit'
      })
    });
  }
  cursor.setTime(cursor.getTime() + SLOT_MIN * 60 * 1000);
}

return [{
  json: {
    proposed_slots: freeSlots,
    calendar_id: staffData.calendar_id || '',
    staff_email: staffData.email || '',
    staff_name: staffData.name || ''
  }
}];

